<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import {refreshAll} from '$app/navigation';
 import type {AppData} from '#lib/client/types.ts';
 import {command,permitted} from '#lib/client/api.ts';
 import ReferencePicker from './ReferencePicker.svelte';
 import Status from './Status.svelte';
 let {data}:{data:AppData}=$props();
 let selected:string[]=$state([]),targetType=$state(''),targetId=$state(''),confirmed=$state(false),busy=$state(false),error=$state(''),notice=$state(''),excludeReason=$state('');
 const batch=$derived(data.detail!),all=$derived(data.related?.archive_entries??[]),entries=$derived(all.slice(0,100));
 const targets=$derived([{value:'',name:'Interne Dokumentablage',permission:'documents'},{value:'customers',name:'Kundenakte',permission:'crm'},{value:'orders',name:'Auftragsakte',permission:'orders'},{value:'suppliers',name:'Lieferantenakte',permission:'purchasing'},{value:'team',name:'Personalakte',permission:'hr'}].filter(t=>permitted(data,t.permission)));
 const forbidden=(row:any)=>!row.metadata?.size||/\.(zip|7z|rar|tar|gz|bz2|xz|exe|dll|bat|cmd|ps1|com|scr|msi|js|html?)$/i.test(row.path);
 function toggle(id:string){selected=selected.includes(id)?selected.filter(v=>v!==id):selected.length<20?[...selected,id]:selected;confirmed=false;}
 async function finish(){busy=true;error='';try{await command('migration.drive.complete',batch.id,{},batch.version);notice='Die Charge ist vollst?ndig gepr?ft und abgeschlossen.';await refreshAll();}catch(e){error=e instanceof Error?e.message:'Charge kann noch nicht abgeschlossen werden.';}finally{busy=false;}}
 async function exclude(id:string){if(excludeReason.trim().length<10){error='Bitte zuerst einen nachvollziehbaren Ausschlussgrund eintragen (mindestens10Zeichen).';return;}busy=true;error='';try{await command('migration.drive.exclude',batch.id,{entry_ids:[id],reason:excludeReason.trim()},batch.version);selected=selected.filter(v=>v!==id);await refreshAll();}catch(e){error=e instanceof Error?e.message:'Ausschluss nicht m?glich.';}finally{busy=false;}}
 async function extract(){if(busy||!confirmed||!selected.length||targetType&&!targetId)return;busy=true;error='';notice='';try{await command('migration.drive.extract',batch.id,{selections:selected.map(entry_id=>({entry_id,target_type:targetType||null,target_id:targetType?targetId:null})),access_statement:'Die ausgewählten Originale gehören zu der konkret gewählten internen Akte. Die Berechtigungen und Herkunft wurden für diese Auswahl geprüft.'},batch.version);selected=[];confirmed=false;notice='Die ausgewählten Originale werden übernommen und einzeln auf Schadsoftware geprüft. Aktualisieren Sie den Stand nach Abschluss der Verarbeitung.';await refreshAll();}catch(e){error=e instanceof Error?e.message:'Übernahme nicht möglich. Ihre Auswahl bleibt erhalten.';}finally{busy=false;}}
</script>
{#if batch.inventory_hash||all.length}
<section class="panel"><header class="panel-header"><div><h2>Ordnerexport prüfen</h2><p class="small muted">{batch.checkpoint??0} von {batch.validation_report?.entries??all.length} Originalen übernommen</p></div><Status value={batch.status}/></header><div class="panel-body stack">
 <p>Das Inventar enthält die ursprünglichen Pfade. Wählen Sie bis zu20Dateien und ordnen Sie diese einer berechtigten Akte zu. Die Quelldateien bleiben erhalten.</p>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}
 <div class="table-scroll"><table class="data-table"><thead><tr><th>Auswahl</th><th>Ursprünglicher Pfad</th><th>Größe</th><th>Stand</th></tr></thead><tbody>{#each entries as entry}<tr><td><input type="checkbox" aria-label={`${entry.path} auswählen`} checked={selected.includes(entry.id)} disabled={busy||batch.status!=='inventory_ready'||!!entry.document_id||entry.status==='excluded'||forbidden(entry)||selected.length>=20&&!selected.includes(entry.id)} onchange={()=>toggle(entry.id)}/></td><td><span class="path">{entry.path}</span>{#if entry.last_error}<p class="field-error">{entry.last_error}</p>{/if}{#if forbidden(entry)}<p class="field-help">Leere Dateien, verschachtelte Archive und ausführbare Inhalte werden nicht übernommen.</p>{/if}{#if entry.document_id}<a class="text-link" href={`/documents/${entry.document_id}`}>Übernommenes Original öffnen</a>{/if}</td><td>{new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(Number(entry.metadata?.size??0)/1024)}KB</td><td><Status value={entry.status}/>{#if batch.status==='inventory_ready'&&!entry.document_id&&entry.status!=='excluded'}<button class="btn small" type="button" disabled={busy||excludeReason.trim().length<10} onclick={()=>exclude(entry.id)} aria-label={`${entry.path} begr?ndet ausschlie?en`}>Ausschlie?en</button>{/if}</td></tr>{/each}</tbody></table></div>
 <div class="row"><a class="text-link" href={`/imports/${batch.id}`}>Erste Seite</a>{#if all.length>100}<a class="text-link" href={`/imports/${batch.id}?archive_after=${encodeURIComponent(entries.at(-1)?.path??'')}`}>Nächste100Originale</a>{/if}<button class="btn small" type="button" onclick={()=>refreshAll()} disabled={busy}>Stand aktualisieren</button></div>
 {#if batch.status==='inventory_ready'&&permitted(data,'documents.upload')}<div class="form-field"><label for="drive-exclude-reason">Begr?ndung f?r einen Ausschluss</label><input id="drive-exclude-reason" bind:value={excludeReason} placeholder="Zum Beispiel: Leere Vorschaudatei ohne fachlichen Inhalt"/><p class="field-help">Nur verwenden, wenn ein Original bewusst nicht ?bernommen werden soll. Der Grund bleibt bei der Datei erhalten.</p></div><form class="stack" onsubmit={(event)=>{event.preventDefault();extract();}}><div class="form-field"><label for="drive-target">Ziel für die ausgewählten Originale</label><select use:searchableSelect={targetType} id="drive-target" bind:value={targetType} onchange={()=>{targetId='';confirmed=false;}}>{#each targets as target}<option value={target.value}>{target.name}</option>{/each}</select><p class="field-help">Jede Datei erhält die Rechte ihrer Zielakte. Gleiche Dateiinhalte verbinden keine Kunden- oder Personalberechtigungen.</p></div>{#if targetType}<div class="form-field"><label for="drive-target-record">Konkrete Akte</label>{#key targetType}<ReferencePicker id="drive-target-record" bind:value={targetId} reference={targetType} required/>{/key}</div>{/if}<label class="confirm"><input type="checkbox" bind:checked={confirmed}/>Ich habe die Herkunft und die Berechtigung der {selected.length} ausgewählten Originale für diese Akte geprüft.</label><div><button class="btn primary" disabled={busy||!confirmed||!selected.length||!!targetType&&!targetId}>{busy?'Übernahme wird vorbereitet …':`${selected.length} Originale übernehmen`}</button></div></form><div><button class="btn" type="button" disabled={busy} onclick={finish}>Gepr?fte Charge abschlie?en</button><p class="field-help">Erst m?glich, wenn alle Originale gepr?ft ?bernommen oder begr?ndet ausgeschlossen wurden.</p></div>{:else if batch.status==='extracting'}<div class="notice info">Die Auswahl wird verarbeitet. Bereits übernommene Originale bleiben als Checkpoint gespeichert; ein erneuter Versuch überspringt diese Dateien.</div>{/if}
</div></section>
{/if}
<style>.path{overflow-wrap:anywhere}.row{display:flex;align-items:center;gap:20px;flex-wrap:wrap}.confirm{display:flex;align-items:flex-start;gap:12px;line-height:1.6}.confirm input{margin-top:5px}.form-field{max-width:560px}input[type=checkbox]{width:20px;height:20px;min-height:20px}</style>
